u32 kvm_apic_get_current_count(struct kvm_lapic *apic) {
    u64 period, remaining, bus_cycle;
    u32 count;

    if (!apic)
        return 0;

    if (apic->base.read_register(apic, APIC_TMICT) == 0)
        return 0;

    period = apic->base.read_register(apic, APIC_TDCR) & 0x0f;
    if (period == 0)
        return 0;

    remaining = apic->base.read_register(apic, APIC_TMICT) - apic->base.read_register(apic, APIC_TMR);
    if (remaining < 0)
        remaining = 0;

    bus_cycle = (1000000000ULL << period) / APIC_BUS_CYCLE_HZ;
    count = (u32)(remaining % bus_cycle) / (1ULL << apic->base.read_register(apic, APIC_TDCR));

    return count;
}
